<template>
        <div class="layout-px-spacing bg-white"> 
            <button
            data-bs-toggle="modal"
            data-bs-target="#budgetConsumption"
            >open</button> 

                <div class="modal fade" id="budgetConsumption" tabindex="-1" role="dialog" aria-labelledby="editModalLabel" aria-hidden="true">
    <div class="modal-dialog modal-fullscreen modal-dialog-scrollable" role="document"> <!-- Changed to modal-xl and added scrollable -->
        <div class="modal-content"> <!-- Added min-height -->
            <div class="modal-header">
                <h5 class="modal-title" id="editModalLabel">BUDGET STATEMENT FOR</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
            </div>
            <div class="modal-body">
                              <div
            v-if="loading" v-html="tableShimmer()"
            ></div>
            <div v-else>
                <table  class="table table-bordered table-responsive mb-3">
          <thead>
            <tr>
              <th colspan="8" class="bg-light text-center text-dark fs-6 mt-5">Budget Details</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <th>Project:</th>
              <td>{{ budgetLine.project }}</td>
              <th>Budget Name:</th>
              <td>{{ budgetLine.budget }}</td>
               <th>Budget Category:</th>
              <td>{{ budgetLine.category}}</td>
            </tr>
           <tr>
            <th>Description:</th>
            <td colspan="5">{{ budgetLine.item }}</td>

           </tr>
            <tr>
              <th>Budget Cost:</th>
              <td>{{ formatNumber(budgetLine.budget_cost) }} Tsh</td>
              <th>Used Cost:</th>
              <td>{{ formatNumber(budgetLine.budget_cost - 1450) }} Tsh</td>
              <th>Balance:</th>
              <td>{{ formatNumber(budgetLine.budget_cost - 1450) }} Tsh</td>
            </tr>
          </tbody>
        </table>

                <h5>TRANSACTIONS</h5>
            <div          
            class="panel p-0" >
              <div class="custom-table table3"   style="max-height: 95vh; overflow-y: auto;">
                <v-client-table :data="consumptions" :columns="consuptionColumns" >
                   <template #actions="props">                        
                             <svg xmlns="http://www.w3.org/2000/svg"
                              v-if="user_permissions.includes('can_delete_budget_description_remark')" 
                                 width="26"
                                  height="26"                                 
                                   fill="currentColor"
                                    class="bi bi-trash text-danger me-2"
                                     @click="deleteBudgetRemark(props.row,budget_description)"
                                     viewBox="0 0 16 16">
                                    <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
                                    <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"/>
                                </svg>
                                <router-link :to="`/approval/${props.row.approval_id}`">
                          <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" fill="currentColor" class="bi bi-arrow-right" style="cursor: pointer;" viewBox="0 0 16 16">
  <path fill-rule="evenodd" d="M1 8a.5.5 0 0 1 .5-.5h11.793l-3.147-3.146a.5.5 0 0 1 .708-.708l4 4a.5.5 0 0 1 0 .708l-4 4a.5.5 0 0 1-.708-.708L13.293 8.5H1.5A.5.5 0 0 1 1 8"/>
</svg>
                                </router-link>

                        </template>
                </v-client-table>
              </div>
                          </div>

        </div>
  
        </div>
                          <div class="modal-footer">
                <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>
            </div>
        </div>
            </div>
            
            </div>


        </div>


</template>

<script setup>
    import { onMounted, ref,inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Work Order' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    const tableShimmer = inject('tableShimmer')
    const formatNumber = inject('formatNumber')
    
       const user_permissions = JSON.parse(localStorage.getItem('user')).permissions

const props = defineProps({
    workOrderId: String
});

   const consuptionColumns = [ 'sno','authorized_by','date' ,'description','debit','credit','balance','actions'];

const consumptions = ref([])
const loading = ref(false)
const balance = ref(0)
const getBudgetConsuption = async (desc) => {
  
  consumptions.value = [];
  loading.value = true;

  // initialize balance from desc.cost
  balance.value = parseFloat(budgetLine.value.budget_cost);

  const response = await axiosInstance.get(
    `budget-remarks?budget_item_description_id=1214`
  );

  consumptions.value = response.data.map((data, i) => {
    balance.value -= parseFloat(data.cost);
    return {
      ...data,
      sno: i + 1,
      id: data.id,
      authorized_by: data.remarker.name,
      date: data.date,
      debit: data.cost > 0 ? Number(data.cost).toLocaleString() + " Tsh" : "--",
      credit:
        data.cost < 0
          ? Number(Math.abs(data.cost)).toLocaleString() + " Tsh"
          : "--",
      description: data.description,
      balance: balance.value.toLocaleString() + " Tsh",
    };
  });

  loading.value = false;
};


const budgetLine = ref('')
const getBudget = async()=>{
    const response = await axiosInstance.get('budget-line?line_id=1214')
    budgetLine.value = response.data
}


    onMounted(async() => {
        await getBudget()
        getBudgetConsuption()
    });
</script>

